package com.dtm.platform.controller;import com.dtm.platform.service.*;import com.dtm.platform.repository.*;import com.dtm.platform.entity.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;import java.io.*;
@RestController @RequestMapping("/api/v1") public class MediaController {
 private final MediaService media;private final MediaRepository repository;public MediaController(MediaService media,MediaRepository repository){this.media=media;this.repository=repository;}
 private Map<String,Object> dto(Media m){return Map.of("id",m.id,"name",m.name,"contentType",m.contentType,"size",m.size,"createdAt",m.createdAt,"url","/api/v1/media/"+m.id+"/download");}
 @PostMapping("/admin/media") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public Map<String,Object> upload(@RequestParam("file") MultipartFile file)throws IOException{return dto(media.upload(file));}
 @GetMapping("/admin/media") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public com.dtm.platform.dto.PageDto<Map<String,Object>> list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){org.springframework.data.jpa.domain.Specification<Media> spec=(root,query,cb)->cb.like(cb.lower(root.get("name")),"%"+q.toLowerCase(java.util.Locale.ROOT)+"%");var out=repository.findAll(spec,org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.max(1,Math.min(100,size)),org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt")));return new com.dtm.platform.dto.PageDto<>(out.map(this::dto).getContent(),out.getTotalElements(),out.getNumber(),out.getSize(),out.getTotalPages());}
 public record RenameInput(String name){}
 @PatchMapping("/admin/media/{id}") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public Map<String,Object> rename(@PathVariable long id,@RequestBody RenameInput in){return dto(media.rename(id,in.name()));}
 @DeleteMapping("/admin/media/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable long id)throws IOException{media.delete(id);}
 @GetMapping("/media/{id}/download") public ResponseEntity<byte[]> download(@PathVariable long id)throws IOException{if(!media.publicReference(id))throw new com.dtm.platform.exception.ApiException(HttpStatus.NOT_FOUND,"File is not published.");var m=media.record(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(m.contentType)).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(m.name).build().toString()).body(media.bytes(m));}
 @GetMapping("/admin/media/{id}/download") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public ResponseEntity<byte[]> adminDownload(@PathVariable long id)throws IOException{var m=media.record(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(m.contentType)).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(m.name).build().toString()).body(media.bytes(m));}
}
